begin;

create table private.public_capsule_drop_places (
  id uuid primary key,
  region_id text not null references private.game_regions(id),
  lat double precision not null check (lat between -90 and 90),
  lng double precision not null check (lng between -180 and 180)
);
alter table private.public_capsule_drop_places enable row level security;
revoke all on private.public_capsule_drop_places from public, anon, authenticated, service_role;

